import { isHexAddress, isObject, isStrictHexString } from '@metamask/utils';
import type { Hex } from '@metamask/utils';
import { validatedVersionGatedFeatureFlag } from '../remote-feature-flag-utils';

/**
 * The LaunchDarkly flag that gates the Money Account surface. The same flag
 * name and shape mobile reads in `app/lib/Money/feature-flags.ts`, so the two
 * clients turn on and off together.
 */
export const MONEY_ENABLE_MONEY_ACCOUNT_FLAG_NAME = 'moneyEnableMoneyAccount';

/**
 * The LaunchDarkly flag listing ISO country codes that must not be offered
 * Money Account. Same name and `{ blockedRegions }` shape as mobile.
 */
export const MONEY_ACCOUNT_GEO_BLOCKED_COUNTRIES_FLAG_NAME =
  'moneyAccountGeoBlockedCountries';

/**
 * Blocked countries used when the remote geo flag is absent or malformed.
 * Matches mobile's `DEFAULT_MONEY_ACCOUNT_BLOCKED_COUNTRIES`.
 */
export const DEFAULT_MONEY_ACCOUNT_BLOCKED_COUNTRIES = ['GB'];

/**
 * Sentinel returned by GeolocationController when the location is not yet
 * determined or the API returned an invalid response.
 */
const UNKNOWN_LOCATION = 'UNKNOWN';

/**
 * The LaunchDarkly flag that gates the Money balance card on the wallet home
 * screen, independently of {@link MONEY_ENABLE_MONEY_ACCOUNT_FLAG_NAME}.
 */
export const MONEY_HOME_SCREEN_CARD_ENABLED_FLAG_NAME =
  'moneyHomeScreenCardEnabled';

/**
 * The LaunchDarkly flag that gates the realized Earnings section on Money
 * Home.
 */
export const MONEY_EARNING_SECTION_ENABLED_FLAG_NAME =
  'earnMoneyEarningSectionEnabled';

/**
 * The LaunchDarkly flag that injects curated Money activity rows for UI
 * review. Same name and plain-boolean shape as mobile.
 */
export const MONEY_ACTIVITY_MOCK_DATA_ENABLED_FLAG_NAME =
  'moneyActivityMockDataEnabled';

/**
 * The LaunchDarkly flag that gates navigation from Money activity rows to
 * the transaction details page. Same name as mobile.
 */
export const MONEY_ENABLE_ACTIVITY_DETAILS_FLAG_NAME =
  'moneyEnableActivityDetails';

/**
 * The LaunchDarkly flag that gates the "Get X% APY" Money deposit CTA on
 * token list rows. Same name and version-gated shape as mobile.
 */
export const MONEY_TOKEN_LIST_ITEM_CTA_ENABLED_FLAG_NAME =
  'earnMoneyTokenListItemCtaEnabled';

/**
 * The LaunchDarkly flag that gates the dismissible "Earn up to X% APY" Money
 * banner on token details. Same name and version-gated shape as mobile.
 */
export const MONEY_EARN_BANNER_ENABLED_FLAG_NAME = 'earnMoneyEarnBannerEnabled';

/**
 * The LaunchDarkly flag that gates the Money earn CTA in the token details
 * "Your balance" section. Same name and version-gated shape as mobile.
 */
export const MONEY_ASSET_OVERVIEW_BALANCE_CTA_ENABLED_FLAG_NAME =
  'earnMoneyAssetOverviewBalanceCtaEnabled';

/**
 * The LaunchDarkly flag listing, per hex chain ID, the ERC-20 addresses that
 * get Money deposit CTAs. Same name and `{ [chainId]: address[] }` shape as
 * mobile.
 */
export const MONEY_DEPOSIT_CTA_TOKEN_ADDRESSES_FLAG_NAME =
  'earnMoneyDepositCtaTokenAddresses';

export type MoneyTokenAddressList = Record<Hex, Hex[]>;

/**
 * Whether the Money Account feature is enabled.
 *
 * The flag is version-gated, so an absent, malformed, or below-minimum-version
 * value means "off" — the surface stays hidden rather than defaulting on.
 *
 * @param remoteFeatureFlags - The remote feature flags.
 * @returns Whether the Money Account feature is enabled.
 */
export function isMoneyAccountEnabled(
  remoteFeatureFlags: Record<string, unknown> | undefined,
): boolean {
  return (
    validatedVersionGatedFeatureFlag(
      remoteFeatureFlags?.[MONEY_ENABLE_MONEY_ACCOUNT_FLAG_NAME],
    ) ?? false
  );
}

/**
 * The geo-blocked countries for Money Account from remote config, or the
 * local fallback when the flag is unserved or malformed.
 *
 * An empty remote `blockedRegions` array is valid and means nobody is
 * blocked. Only a missing or non-array value falls back to
 * {@link DEFAULT_MONEY_ACCOUNT_BLOCKED_COUNTRIES}.
 *
 * @param remoteFeatureFlags - The remote feature flags.
 * @returns ISO country codes that must not be offered Money Account.
 */
export function getMoneyAccountGeoBlockedCountries(
  remoteFeatureFlags: Record<string, unknown> | undefined,
): string[] {
  const remoteFlag =
    remoteFeatureFlags?.[MONEY_ACCOUNT_GEO_BLOCKED_COUNTRIES_FLAG_NAME];

  if (
    isObject(remoteFlag) &&
    Array.isArray(remoteFlag.blockedRegions) &&
    remoteFlag.blockedRegions.every(
      (region): region is string => typeof region === 'string',
    )
  ) {
    return remoteFlag.blockedRegions;
  }

  return DEFAULT_MONEY_ACCOUNT_BLOCKED_COUNTRIES;
}

/**
 * Whether the user's detected region is allowed to see Money Account.
 *
 * Defaults to blocking when geolocation is unknown so a failed or pending
 * lookup cannot bypass a blocked region. Matching uses the country segment
 * only (`"US-TX"` → `"US"`) and case-insensitive `startsWith`, so `"GB"`
 * also blocks `"GB-ENG"`. An empty blocked list means nobody is blocked.
 *
 * @param location - GeolocationController country/region code, or `UNKNOWN`.
 * @param blockedCountries - ISO country codes from
 * {@link getMoneyAccountGeoBlockedCountries}.
 * @returns Whether the user is geo-eligible for Money Account.
 */
export function isMoneyAccountGeoEligible(
  location: string | undefined | null,
  blockedCountries: string[],
): boolean {
  if (!location || location === UNKNOWN_LOCATION) {
    return false;
  }

  const userCountry = location.toUpperCase().split('-')[0];
  if (!userCountry) {
    return false;
  }

  if (blockedCountries.length === 0) {
    return true;
  }

  return blockedCountries.every(
    (blocked) => !userCountry.startsWith(blocked.toUpperCase()),
  );
}

/**
 * Whether the Money balance card on the wallet home screen is enabled.
 *
 * The flag is version-gated and fails closed when absent, malformed, or below
 * the current extension version.
 *
 * This says nothing about whether Money Account itself is enabled; callers
 * must also gate on {@link isMoneyAccountEnabled}.
 *
 * @param remoteFeatureFlags - The remote feature flags.
 * @returns Whether the home screen card is enabled.
 */
export function isMoneyHomeScreenCardEnabled(
  remoteFeatureFlags: Record<string, unknown> | undefined,
): boolean {
  return (
    validatedVersionGatedFeatureFlag(
      remoteFeatureFlags?.[MONEY_HOME_SCREEN_CARD_ENABLED_FLAG_NAME],
    ) ?? false
  );
}

/**
 * Whether the realized Earnings section on Money Home is enabled.
 *
 * The flag is version-gated and fails closed when absent, malformed, or below
 * the current extension version.
 *
 * @param remoteFeatureFlags - The remote feature flags.
 * @returns Whether the Earnings section is enabled.
 */
export function isMoneyEarningSectionEnabled(
  remoteFeatureFlags: Record<string, unknown> | undefined,
): boolean {
  return (
    validatedVersionGatedFeatureFlag(
      remoteFeatureFlags?.[MONEY_EARNING_SECTION_ENABLED_FLAG_NAME],
    ) ?? false
  );
}

/**
 * Whether Money Home should render curated mock activity instead of a live
 * transaction list.
 *
 * A remote boolean wins (including `false`). Any other remote value falls
 * through to {@link MONEY_ACTIVITY_MOCK_DATA_ENABLED_ENV_VAR}.
 *
 * @param remoteFeatureFlags - The remote feature flags.
 * @returns Whether mock activity data is enabled.
 */
export function isMoneyActivityMockDataEnabled(
  remoteFeatureFlags: Record<string, unknown> | undefined,
): boolean {
  const remote =
    remoteFeatureFlags?.[MONEY_ACTIVITY_MOCK_DATA_ENABLED_FLAG_NAME];
  if (typeof remote === 'boolean') {
    return remote;
  }

  return process.env.MM_MONEY_ACTIVITY_MOCK_DATA_ENABLED?.toString() === 'true';
}

/**
 * Whether tapping a Money activity row should open the transaction details
 * page.
 *
 * A remote boolean wins (including `false`). Any other remote value falls
 * through to `MM_MONEY_ENABLE_ACTIVITY_DETAILS`.
 *
 * @param remoteFeatureFlags - The remote feature flags.
 * @returns Whether activity details navigation is enabled.
 */
export function isMoneyActivityDetailsEnabled(
  remoteFeatureFlags: Record<string, unknown> | undefined,
): boolean {
  const remote = remoteFeatureFlags?.[MONEY_ENABLE_ACTIVITY_DETAILS_FLAG_NAME];
  if (typeof remote === 'boolean') {
    return remote;
  }

  return process.env.MM_MONEY_ENABLE_ACTIVITY_DETAILS?.toString() === 'true';
}

const isMoneyAccountSubFeatureEnabled = (
  remoteFeatureFlags: Record<string, unknown> | undefined,
  flagName: string,
): boolean =>
  isMoneyAccountEnabled(remoteFeatureFlags) &&
  (validatedVersionGatedFeatureFlag(remoteFeatureFlags?.[flagName]) ?? false);

/**
 * Whether the token list row Money deposit CTA is enabled.
 *
 * Both this flag and {@link MONEY_ENABLE_MONEY_ACCOUNT_FLAG_NAME} are
 * version-gated and fail closed.
 *
 * @param remoteFeatureFlags - The remote feature flags.
 * @returns Whether the token list row CTA is enabled.
 */
export function isMoneyTokenListItemCtaEnabled(
  remoteFeatureFlags: Record<string, unknown> | undefined,
): boolean {
  return isMoneyAccountSubFeatureEnabled(
    remoteFeatureFlags,
    MONEY_TOKEN_LIST_ITEM_CTA_ENABLED_FLAG_NAME,
  );
}

/**
 * Whether the token details Money earn banner is enabled.
 *
 * Both this flag and {@link MONEY_ENABLE_MONEY_ACCOUNT_FLAG_NAME} are
 * version-gated and fail closed.
 *
 * @param remoteFeatureFlags - The remote feature flags.
 * @returns Whether the earn banner is enabled.
 */
export function isMoneyEarnBannerEnabled(
  remoteFeatureFlags: Record<string, unknown> | undefined,
): boolean {
  return isMoneyAccountSubFeatureEnabled(
    remoteFeatureFlags,
    MONEY_EARN_BANNER_ENABLED_FLAG_NAME,
  );
}

/**
 * Whether the token details "Your balance" Money earn CTA is enabled.
 *
 * Both this flag and {@link MONEY_ENABLE_MONEY_ACCOUNT_FLAG_NAME} are
 * version-gated and fail closed.
 *
 * @param remoteFeatureFlags - The remote feature flags.
 * @returns Whether the balance CTA is enabled.
 */
export function isMoneyAssetOverviewBalanceCtaEnabled(
  remoteFeatureFlags: Record<string, unknown> | undefined,
): boolean {
  return isMoneyAccountSubFeatureEnabled(
    remoteFeatureFlags,
    MONEY_ASSET_OVERVIEW_BALANCE_CTA_ENABLED_FLAG_NAME,
  );
}

const parseTokenAddressList = (
  raw: unknown,
): MoneyTokenAddressList | undefined => {
  let value = raw;
  if (typeof raw === 'string') {
    try {
      value = JSON.parse(raw);
    } catch {
      return undefined;
    }
  }

  if (!isObject(value) || Array.isArray(value)) {
    return undefined;
  }

  const result: MoneyTokenAddressList = {};
  for (const [chainId, addresses] of Object.entries(value)) {
    if (
      !isStrictHexString(chainId) ||
      !Array.isArray(addresses) ||
      !addresses.every(
        (address) =>
          typeof address === 'string' && isHexAddress(address.toLowerCase()),
      )
    ) {
      return undefined;
    }

    const normalizedChainId = `0x${BigInt(chainId).toString(16)}` as Hex;
    result[normalizedChainId] = [
      ...(result[normalizedChainId] ?? []),
      ...addresses.map((address) => address.toLowerCase() as Hex),
    ];
  }

  return result;
};

/**
 * The ERC-20 tokens, per chain, that get Money deposit CTAs.
 *
 * Accepts an object or a JSON string. Chain IDs are normalized (`0x01` →
 * `0x1`) and addresses lowercased. Any malformed entry invalidates the whole
 * flag, which then resolves to an empty list so no CTA is shown.
 *
 * @param remoteFeatureFlags - The remote feature flags.
 * @returns The normalized token address list.
 */
export function getMoneyDepositCtaTokenAddresses(
  remoteFeatureFlags: Record<string, unknown> | undefined,
): MoneyTokenAddressList {
  return (
    parseTokenAddressList(
      remoteFeatureFlags?.[MONEY_DEPOSIT_CTA_TOKEN_ADDRESSES_FLAG_NAME],
    ) ?? {}
  );
}
